    function ensureWorkerRun(flow, childMeta, at = Date.now()) {
      if (!flow || !childMeta?.id) return flow;
      const existing = flow.runs.find((r) => r.id === childMeta.id);
      let next = flow;
      if (!existing || existing.status !== "running") {
        next = reduce(next, {
          type: "run.start",
          at,
          id: childMeta.id,
          harness: "opencode",
          role: "worker",
          agent: childMeta.agent || "self",
          ...(childMeta.title ? { title: childMeta.title } : {}),
          model: childMeta.model || "unknown",
          effort: childMeta.effort || "high",
        });
      } else if (
        existing.model === "unknown" &&
        childMeta.model &&
        childMeta.model !== "unknown"
      ) {
        next = {
          ...next,
          runs: next.runs.map((r) =>
            r.id === childMeta.id
              ? {
                  ...r,
                  model: childMeta.model,
                  effort: childMeta.effort || r.effort,
                  ...(childMeta.agent ? { agent: childMeta.agent } : {}),
                }
              : r,
          ),
        };
      }
      const tokens = getSessionTokens(childMeta.id);
      if (
        tokens.input > 0 ||
        tokens.output > 0 ||
        tokens.cacheRead > 0 ||
        tokens.cacheWrite > 0
      ) {
        next = reduce(next, {
          type: "run.progress",
          at,
          id: childMeta.id,
          tokens,
        });
      }
      return next;
    }

    /** @type {Set<string>} */
    const wokenMentions = new Set();

    /** @type {Map<string, import('./lib/orchestrator-core.mjs').FlowEvent>} */
    const pendingTeamByRoot = new Map();

    async function isKnownChildSession(sessionID) {
      if (!sessionID) return false;
      const cached = sessionMeta.get(sessionID);
      if (cached?.parentID) return true;
      if (typeof ctx?.session?.get === "function") {
        try {
          const info = await ctx.session.get({ sessionID });
          if (info && typeof info === "object" && info.parentID) {
            let rootID = info.parentID;
            const parentCached = sessionMeta.get(info.parentID);
            if (parentCached?.rootID) {
              rootID = parentCached.rootID;
            }
            const meta = upsertSessionMeta(sessionID, {
              parentID: info.parentID,
              title: info.title,
              agent: info.agent,
              modelRef: info.model,
              verified: true,
            });
            if (meta) {
              meta.rootID = rootID;
              sessionMeta.set(meta.id, meta);
            }
            return true;
          }
        } catch {
          return false;
        }
      }
      return false;
    }

    async function deliverPendingWakes(rootID) {
      if (!rootID || typeof ctx?.session?.prompt !== "function") return;
      const initial = flowsByRoot.get(rootID);
      if (!initial || initial.closedAt) return;

      const wakes = pendingWakes(initial);
      // Wakes for the root (lead) session are grouped by post, so a post that
      // mentions @lead and a helper with no session of its own reaches the
      // lead once (with the "Wake @helper" line), not once per mentioned name.
      const sends = [];
      const leadSendBySeq = new Map();
      for (const wake of wakes) {
        const current = flowsByRoot.get(rootID);
        if (!current || current.closedAt) break;
        const wakeKey = `${wake.seq}:${wake.target}`;
        const scopedKey = `${rootID}:${current.startedAt}:${wakeKey}`;
        if (
          wokenMentions.has(scopedKey) ||
          (Array.isArray(current.woken) && current.woken.includes(wakeKey))
        ) {
          continue;
        }
        const post = Array.isArray(current.posts)
          ? current.posts.find((p) => p.seq === wake.seq)
          : undefined;

        if (wake.target !== "lead") {
          const baseRunId = wake.runId ? String(wake.runId).split("#")[0] : "";
          const candidateChildID = baseRunId || wake.runId || "";
          let knownChild = false;
          try {
            knownChild = Boolean(
              candidateChildID && (await isKnownChildSession(candidateChildID)),
            );
          } catch {
            knownChild = false;
          }
          if (knownChild) {
            sends.push({
              sessionID: candidateChildID,
              post,
              wakes: [wake],
              toLead: false,
            });
            continue;
          }
        }
        const existing = leadSendBySeq.get(wake.seq);
        if (existing) {
          existing.wakes.push(wake);
        } else {
          const send = { sessionID: rootID, post, wakes: [wake], toLead: true };
          leadSendBySeq.set(wake.seq, send);
          sends.push(send);
        }
      }

      for (const send of sends) {
        const current = flowsByRoot.get(rootID);
        if (!current || current.closedAt) break;
        const scopedKeys = send.wakes.map(
          (w) => `${rootID}:${current.startedAt}:${w.seq}:${w.target}`,
        );
        if (scopedKeys.some((k) => wokenMentions.has(k))) continue;
        for (const k of scopedKeys) wokenMentions.add(k);
        try {
          const text = send.toLead
            ? formatLeadWakes(send.wakes, send.post, { harness: "opencode" })
            : formatWake(send.wakes[0], send.post, {
                mode: "worker",
                harness: "opencode",
              });
          await ctx.session.prompt({ sessionID: send.sessionID, text });
          const latest = flowsByRoot.get(rootID);
          if (latest) {
            let wokenFlow = latest;
            for (const w of send.wakes) {
              wokenFlow = reduce(wokenFlow, {
                type: "wake",
                at: Date.now(),
                seq: w.seq,
                target: w.target,
              });
            }
            persistFlow(rootID, wokenFlow);
          }
        } catch {
          // Swallow prompt errors; remove in-flight keys so a later pass retries.
          for (const k of scopedKeys) wokenMentions.delete(k);
        }
